//! 🧪️ Original boxed payloads and refusing issuers preserve actual allocator custody.
use super::*;
use crate::{observe_retirement_allocations,retirement::{controlled::ControlledRetirement,admit_owned_retirement,owned_retirement_birth_bytes,shared::arc_bytes},FactoryPayloadRetirement,retained_clone::RetainedCloneStep};
use std::sync::atomic::{AtomicBool,Ordering};
struct Issuer{refuse:AtomicBool}
impl FactoryPayloadRetirement for Issuer{
 type CloseState=bool;
 fn close_state_birth_bytes(&self)->usize{0}
 fn close_state_constructor_depth(&self)->usize{0}
 fn prepare_close_state(&self)->bool{false}
 fn transfer_payload(_:Self,state:&mut bool){*state=true;}
 fn close_state_demands(_: &bool,_:usize)->Result<RetirementDemand,ValueError>{Ok(Default::default())}
 fn close_state_step(state:&mut bool,_:RetainedCloneGrant)->Result<RetainedCloneStep,ValueError>{assert!(*state);Ok(RetainedCloneStep::Complete(Default::default()))}
 fn close_state_terminal_is_empty(state:&bool)->bool{*state}
}
#[test]
fn factory_boxed_publication_handoff_retains_original_allocations_without_release(){
 let law:serde_json::Value=serde_json::from_str(include_str!("../🧫️fixtures/🔣️.json")).unwrap();
 for row in law["cases"].as_array().unwrap(){let mut text=String::with_capacity(row["capacity"].as_u64().unwrap()as usize);text.push_str(row["text"].as_str().unwrap());let pointer=text.as_ptr();let factory:Arc<dyn ArtifactOwnedValueRetirementFactory<String>>=Arc::new(Issuer{refuse:AtomicBool::new(false)});let source=Box::new(FactoryBoxedValue{original:Box::new(text),factory});let held=std::mem::size_of::<String>()+std::mem::size_of::<FactoryBoxedValue<String>>()+arc_bytes::<Issuer>();let((value,retired),heap)=observe_retirement_allocations(||source.take_for_publication());assert_eq!(heap,(0,0));assert_eq!(value.as_ptr(),pointer);assert_eq!(value,row["text"].as_str().unwrap());let mut owner=ControlledRetirement::new(retired).map_err(|(error,_)|error).unwrap();let(mut births,mut releases)=(0,0);for turn in 0..100000{if owner.terminal_is_empty(){break;}let copy=owner.next_copy_byte_demand().unwrap().max(1);let release=owner.next_release_byte_demand().unwrap();let grant=RetainedCloneGrant{maximum_items:1,maximum_copy_bytes:copy,maximum_capacity_bytes:owner.next_capacity_byte_demand(if copy>0{copy}else{release}).unwrap(),maximum_release_bytes:release,maximum_depth:owner.next_depth_demand().unwrap()};let(step,heap)=observe_retirement_allocations(||owner.step(grant).unwrap());assert!(step.progress().fits(grant));assert_eq!(heap,(step.progress().retained_capacity_bytes,step.progress().released_bytes));births+=heap.0;releases+=heap.1;assert!(turn<99999);}assert!(owner.terminal_is_empty());assert_eq!(releases,held+births);let(_,heap)=observe_retirement_allocations(||drop(owner));assert_eq!(heap,(0,0));assert_eq!(value.as_ptr(),pointer);eprintln!("[DEBUG] Actual boxed publication handoff0allocation0release original payload retained; carrier and payload box extents plus issuer released under caller grants; original={held} born={births} released={releases}");}
}
#[test]
fn factory_boxed_refused_publication_restores_the_actual_original_slots_and_issuer(){
 let law:serde_json::Value=serde_json::from_str(include_str!("../🧫️fixtures/🔣️.json")).unwrap();for row in law["cases"].as_array().unwrap(){let mut text=String::with_capacity(row["capacity"].as_u64().unwrap()as usize);text.push_str(row["text"].as_str().unwrap());let factory:Arc<dyn ArtifactOwnedValueRetirementFactory<String>>=Arc::new(Issuer{refuse:AtomicBool::new(false)});let source=Box::new(FactoryBoxedValue{original:Box::new(text),factory});let carrier=source.as_ref()as*const FactoryBoxedValue<String>;let payload=source.original.as_ref()as*const String;let bytes=source.original.as_ptr();let issuer=Arc::as_ptr(&source.factory);let((value,retired),heap)=observe_retirement_allocations(||source.take_for_publication());assert_eq!(heap,(0,0));let(restored,heap)=observe_retirement_allocations(||retired.restore(value));assert_eq!(heap,(0,0));assert_eq!(restored.as_ref()as*const FactoryBoxedValue<String>,carrier);assert_eq!(restored.original.as_ref()as*const String,payload);assert_eq!(restored.original.as_ptr(),bytes);assert!(std::ptr::addr_eq(Arc::as_ptr(&restored.factory),issuer));let mut owner=ControlledRetirement::new(restored).map_err(|(error,_)|error).unwrap();for turn in 0..100000{if owner.terminal_is_empty(){break;}let copy=owner.next_copy_byte_demand().unwrap();let release=owner.next_release_byte_demand().unwrap();let grant=RetainedCloneGrant{maximum_items:1,maximum_copy_bytes:copy,maximum_capacity_bytes:owner.next_capacity_byte_demand(if copy>0{copy}else{release}).unwrap(),maximum_release_bytes:release,maximum_depth:owner.next_depth_demand().unwrap()};let(step,heap)=observe_retirement_allocations(||owner.step(grant).unwrap());assert_eq!(heap,(step.progress().retained_capacity_bytes,step.progress().released_bytes));assert!(step.progress().fits(grant));assert!(turn<99999);}assert!(owner.terminal_is_empty());eprintln!("[DEBUG] Refused publication restored actual carrier/payload/byte/issuer addresses, heap0; caller then retired all original allocations");}
}
impl ArtifactOwnedValueRetirementFactory<String> for Issuer{
 fn retirement_birth_bytes(&self,_:&String)->usize{owned_retirement_birth_bytes::<String>()}
 fn retire_owned(&self,value:String,grant:RetainedCloneGrant)->Result<(Box<dyn ErasedSnapshotRetirement>,RetainedCloneProgress),(ValueError,String)>{if self.refuse.swap(false,Ordering::SeqCst){Err((ValueError::literal(ValueRefusalKind::OwnershipLimit,"original boxed issuer refuses once"),value))}else{admit_owned_retirement(value,grant)}}
}
#[test]
fn factory_boxed_value_preserves_original_box_payload_issuer_and_exact_physical_receipts(){
 let law:serde_json::Value=serde_json::from_str(include_str!("../🧫️fixtures/🔣️.json")).unwrap();
 for row in law["cases"].as_array().unwrap(){for body in law["copyGrants"].as_array().unwrap(){
  let mut text=String::with_capacity(row["capacity"].as_u64().unwrap()as usize);text.push_str(row["text"].as_str().unwrap());let text_pointer=text.as_ptr();let original=Box::new(text);let box_pointer=original.as_ref()as*const String;let held=original.capacity()+std::mem::size_of::<String>()+arc_bytes::<Issuer>();let factory:Arc<dyn ArtifactOwnedValueRetirementFactory<String>>=Arc::new(Issuer{refuse:AtomicBool::new(true)});let mut owner=ControlledRetirement::new(FactoryBoxedValue{original,factory}).map_err(|(error,_)|error).unwrap();let(mut births,mut releases,mut refusals)=(0,0,0);
  assert_eq!(owner.original().unwrap().original.as_ref()as*const String,box_pointer);
  for turn in 0..1_000_000{if owner.terminal_is_empty(){break;}let copy=owner.next_copy_byte_demand().unwrap().max(body.as_u64().unwrap()as usize);let release=owner.next_release_byte_demand().unwrap();let grant=RetainedCloneGrant{maximum_items:1,maximum_copy_bytes:copy,maximum_capacity_bytes:owner.next_capacity_byte_demand(copy).unwrap(),maximum_release_bytes:release,maximum_depth:owner.next_depth_demand().unwrap()};
   for under in [Some(RetainedCloneGrant{maximum_items:0,..grant}),(owner.next_copy_byte_demand().unwrap()>0).then_some(RetainedCloneGrant{maximum_copy_bytes:owner.next_copy_byte_demand().unwrap().saturating_sub(1),..grant}),(grant.maximum_capacity_bytes>0).then_some(RetainedCloneGrant{maximum_capacity_bytes:grant.maximum_capacity_bytes.saturating_sub(1),..grant}),(release>0).then_some(RetainedCloneGrant{maximum_release_bytes:release.saturating_sub(1),..grant}),(grant.maximum_depth>0).then_some(RetainedCloneGrant{maximum_depth:grant.maximum_depth.saturating_sub(1),..grant})].into_iter().flatten(){let(step,heap)=observe_retirement_allocations(||owner.step(under));match step{Ok(step)=>assert_eq!(step.progress(),Default::default()),Err(error)=>assert!(matches!(error.kind,ValueRefusalKind::DepthLimit|ValueRefusalKind::OwnershipLimit|ValueRefusalKind::WorkLimit))}assert_eq!(heap,(0,0));}
   let(step,(allocated,released))=observe_retirement_allocations(||owner.step(grant));match step{Ok(step)=>{assert!(step.progress().fits(grant));assert_eq!((step.progress().retained_capacity_bytes,step.progress().released_bytes),(allocated,released));births+=allocated;releases+=released;},Err(error)=>{assert_eq!(error.message,"original boxed issuer refuses once");assert_eq!((allocated,released),(0,0));refusals+=1;}}assert!(turn<999999);
  }
  assert_eq!(refusals,1);assert!(owner.terminal_is_empty());assert_eq!(releases,held+births);let(_,heap)=observe_retirement_allocations(||drop(owner));assert_eq!(heap,(0,0));eprintln!("[DEBUG] Boxed factory original={box_pointer:p} bytes={text_pointer:p} copy={body} issuerRefusal=1 actualAllocation={births} actualRelease={releases} terminalDrop=0");
 }}
}
